  "summary": "충북청주 강소특구에서는 특화분야 기업의 기술검증, 대ㆍ중견기업 수요연계 실증사업화 및 이전ㆍ입주기업의 지역 안착을 지원하여 기업의 사업화 가능성과 지역 내 성장 기반을 강화하고자 「2026 충북청주 강소특구 이노테크 기업 육성 통합 지원사업」을 다음과 같이 공고하오니, 참여를 희망하는 기업의 많은 신청 바랍니다. 자세한 사항은 아래 내용을 참고하여 주시기 바랍니다.\n☞ 충북청주 강소특구 내 기업 또는 특구 내 입주 예정기업 중 특화분야 관련 사업을 수행하고 트랙별 신청요건을 충족하는 기업\n※ 특화분야 : 반도체분야, 이차전지분야, 지능형정보화(AI, 양자 등)분야\n※ 자세한 지원대상 공고문 참조\n☞ 기업당 아래 트랙 중 1개를 선택하여 신청\n- (Track 1) 딥테크 사업화 기술 검증(PoC) 지원사업(2차) : 딥테크 시제품 제작 및 기술 검증(기업당 최대 30백만원 이내)\n- (Track 2) 중소기업 대상 대ㆍ중견 수요연계 실증사업화 지원사업(2차) : 대ㆍ중소기업 수요연계 실증사업화(기업당 최대 30백만원 이내)\n- (Track 3) 충북청주 강소특구 이전ㆍ입주기업 지역안착 지원사업 : 시제품 제작 및 마케팅(기업당 최대 10백만원 이내)",
